VALUES ('doc-09-mitre-attack-p0-15487', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-12T17:28:55.345Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CANONSTAGER](https://attack.mitre.org/software/S1237) has abused legitimate executables to side-load malicious DLLs.(Citation: Google Threat Intelligence Group MUSTANG PANDA PLUGX August 2025)", "external_references": [{"description": "Patrick Whitsell. (2025, August 25). Deception in Depth: PRC-Nexus Espionage Campaign Hijacks Web Traffic to Target Diplomats. Retrieved September 9, 2025.", "source_name": "Google Threat Intelligence Group MUSTANG PANDA PLUGX August 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/prc-nexus-espionage-targets-diplomats"}], "id": "relationship--d3b541d4-e179-4595-ba6b-d643ee6398f2", "modified": "2026-04-29T14:23:06.215Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3d1f234e-6c60-43c1-b1f1-6bbc9e5b8e44", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15487', 0, 82, '09-mitre-attack', 'retrieved', 'DB1154CB140B86AB5AB203B21B4A22D9ECD2DBE7BC62F23F6D60CB1CEBF33D8D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
