VALUES ('doc-09-mitre-attack-p0-15488', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-12T17:31:00.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CANONSTAGER](https://attack.mitre.org/software/S1237) has leveraged Native API calls to execute code within the victim’s system including `GetCurrentDirectoryW`, `RegisterClassW` and `CreateWindowExW`.(Citation: Google Threat Intelligence Group MUSTANG PANDA PLUGX August 2025) [CANONSTAGER](https://attack.mitre.org/software/S1237) also created a new overlapped window that initiates callback functions to a windows procedure that processes Windows messages until a designated message type of 0x0018 WM_SHOWWINDOW is observed which then initiates the deployment of a subsequent malicious payload.(Citation: Google Threat Intelligence Group MUSTANG PANDA PLUGX August 2025)", "external_references": [{"description": "Patrick Whitsell. (2025, August 25). Deception in Depth: PRC-Nexus Espionage Campaign Hijacks Web Traffic to Target Diplomats. Retrieved September 9, 2025.", "source_name": "Google Threat Intelligence Group MUSTANG PANDA PLUGX August 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/prc-nexus-espionage-targets-diplomats"}], "id": "relationship--f778f413-7c3c-4265-8e3c-5fc4d538dd64", "modified": "2026-04-29T14:23:06.261Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3d1f234e-6c60-43c1-b1f1-6bbc9e5b8e44", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15488', 0, 139, '09-mitre-attack', 'retrieved', '9A6EFBCBD390C57E84264D12A96F8D5A3606822A1BAFA3CAD0A2CEF311897BF2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
