VALUES ('doc-09-mitre-attack-p0-15526', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-07T15:35:16.901Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AuTo Stealer](https://attack.mitre.org/software/S1029) has the ability to collect information about installed AV products from an infected host.(Citation: MalwareBytes SideCopy Dec 2021)", "external_references": [{"description": "Threat Intelligence Team. (2021, December 2). SideCopy APT: Connecting lures victims, payloads to infrastructure. Retrieved June 13, 2022.", "source_name": "MalwareBytes SideCopy Dec 2021", "url": "https://www.malwarebytes.com/blog/news/2021/12/sidecopy-apt-connecting-lures-to-victims-payloads-to-infrastructure"}], "id": "relationship--e128b6ef-a7a5-4e36-a215-d5a07063c22b", "modified": "2026-04-29T14:23:06.232Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3e4e2c79-2b27-4245-a5c1-5586a3cbd8f5", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15526', 0, 76, '09-mitre-attack', 'retrieved', 'B98E4268FC3F8B075934A9205D23DD823B9E1574C568196C2A66A782A457FA18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
