VALUES ('doc-09-mitre-attack-p0-15533', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-07T16:27:49.467Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShrinkLocker](https://attack.mitre.org/software/S1178) calls [Wevtutil](https://attack.mitre.org/software/S0645) to clear the Windows PowerShell and Microsoft-Windows-Powershell/Operational logs.(Citation: Kaspersky ShrinkLocker 2024)", "external_references": [{"description": "Cristian Souza, Eduardo Ovalle, Ashley Muñoz, & Christopher Zachor. (2024, May 23). ShrinkLocker: Turning BitLocker into ransomware. Retrieved December 7, 2024.", "source_name": "Kaspersky ShrinkLocker 2024", "url": "https://securelist.com/ransomware-abuses-bitlocker/112643/"}], "id": "relationship--64998237-28a6-42ca-8ea5-d6bbfa9f8489", "modified": "2026-04-29T14:23:06.062Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3fc44c12-b16e-4de1-8869-cf0eb4446070", "spec_version": "2.1", "target_ref": "attack-pattern--75b9a4d2-d4e2-4ca1-9aab-1badd9e05fd0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15533', 0, 72, '09-mitre-attack', 'retrieved', '1C179B275EACA8231AA9B9249D00623933D6212D8C88A816579917DAAC0011DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
