VALUES ('doc-09-mitre-attack-p0-15535', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-07T16:25:42.901Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShrinkLocker](https://attack.mitre.org/software/S1178) uses a subdomain on the legitimate Cloudflare resource \"trycloudflare[.]com\" to obfuscate the threat actor''s actual address and to tunnel information sent from victim systems.(Citation: Kaspersky ShrinkLocker 2024)", "external_references": [{"description": "Cristian Souza, Eduardo Ovalle, Ashley Muñoz, & Christopher Zachor. (2024, May 23). ShrinkLocker: Turning BitLocker into ransomware. Retrieved December 7, 2024.", "source_name": "Kaspersky ShrinkLocker 2024", "url": "https://securelist.com/ransomware-abuses-bitlocker/112643/"}], "id": "relationship--74ab1575-0934-4344-bfa7-7cf97015d5c5", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3fc44c12-b16e-4de1-8869-cf0eb4446070", "spec_version": "2.1", "target_ref": "attack-pattern--830c9528-df21-472c-8c14-a036bf17d665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15535', 0, 86, '09-mitre-attack', 'retrieved', '56C768D4C7B464DE29B0771EF52684FB2ECE83E88D0C6C27C5E5B74061A78AF0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
