VALUES ('doc-09-mitre-attack-p0-15540', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-12-07T16:23:28.533Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShrinkLocker](https://attack.mitre.org/software/S1178) disables protectors used to secure the BitLocker encryption key on victim systems.(Citation: Kaspersky ShrinkLocker 2024)(Citation: Splunk ShrinkLocker 2024)", "external_references": [{"description": "Cristian Souza, Eduardo Ovalle, Ashley Muñoz, & Christopher Zachor. (2024, May 23). ShrinkLocker: Turning BitLocker into ransomware. Retrieved December 7, 2024.", "source_name": "Kaspersky ShrinkLocker 2024", "url": "https://securelist.com/ransomware-abuses-bitlocker/112643/"}, {"description": "Splunk Threat Research Team , Teoderick Contreras. (2024, September 5). ShrinkLocker Malware: Abusing BitLocker to Lock Your Data. Retrieved December 7, 2024.", "source_name": "Splunk ShrinkLocker 2024", "url": "https://www.splunk.com/en_us/blog/security/shrinklocker-malware-abusing-bitlocker-to-lock-your-data.html"}], "id": "relationship--bc9ba7ad-2bcb-40e1-8ade-37d03aad8e81", "modified": "2026-04-29T14:23:06.183Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3fc44c12-b16e-4de1-8869-cf0eb4446070", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15540', 0, 106, '09-mitre-attack', 'retrieved', '81FB5933DBCB3DBEA910AD13999099A37AEEA6FF78C049850621FACAEBE0E3BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
