VALUES ('doc-09-mitre-attack-p0-15543', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-09T16:07:29.955Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ShrinkLocker](https://attack.mitre.org/software/S1178) will exit its \"main\" function if the victim domain name does not match provided criteria.(Citation: Splunk ShrinkLocker 2024)", "external_references": [{"description": "Splunk Threat Research Team , Teoderick Contreras. (2024, September 5). ShrinkLocker Malware: Abusing BitLocker to Lock Your Data. Retrieved December 7, 2024.", "source_name": "Splunk ShrinkLocker 2024", "url": "https://www.splunk.com/en_us/blog/security/shrinklocker-malware-abusing-bitlocker-to-lock-your-data.html"}], "id": "relationship--dacadb45-10fd-4f34-b6fe-f63047a3346e", "modified": "2026-04-29T14:23:06.224Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--3fc44c12-b16e-4de1-8869-cf0eb4446070", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15543', 0, 78, '09-mitre-attack', 'retrieved', '551A9CC5AFEDECF86134122886959F26E58BCDD4299B77DB3CAD945107F5686E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
