VALUES ('doc-09-mitre-attack-p0-15574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-07T18:07:47.942Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hildegard](https://attack.mitre.org/software/S0601) has used shell scripts for execution.(Citation: Unit 42 Hildegard Malware)", "external_references": [{"description": "Chen, J. et al. (2021, February 3). Hildegard: New TeamTNT Cryptojacking Malware Targeting Kubernetes. Retrieved April 5, 2021.", "source_name": "Unit 42 Hildegard Malware", "url": "https://unit42.paloaltonetworks.com/hildegard-malware-teamtnt/"}], "id": "relationship--f90759fc-14cb-4f29-a2b6-221d6fb0e884", "modified": "2026-04-29T14:23:06.263Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--40a1b8ec-7295-416c-a6b1-68181d86f120", "spec_version": "2.1", "target_ref": "attack-pattern--a9d4b653-6915-42af-98b2-5758c4ceee56", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15574', 0, 67, '09-mitre-attack', 'retrieved', '3C138B450DFE5977A89D2AAE2FEA43CFB835D74DA2DDC2F0F71162DEFA2F5CA5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
