VALUES ('doc-09-mitre-attack-p0-15575', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agent.btz](https://attack.mitre.org/software/S0092) obtains the victim username and saves it to a file.(Citation: ThreatExpert Agent.btz)", "external_references": [{"description": "Shevchenko, S.. (2008, November 30). Agent.btz - A Threat That Hit Pentagon. Retrieved April 8, 2016.", "source_name": "ThreatExpert Agent.btz", "url": "http://blog.threatexpert.com/2008/11/agentbtz-threat-that-hit-pentagon.html"}], "id": "relationship--6c71a59f-05e6-44cc-ace5-33200e1f0846", "modified": "2026-04-29T14:23:06.073Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--40d3e230-ed32-469f-ba89-be70cc08ab39", "spec_version": "2.1", "target_ref": "attack-pattern--03d7999c-1f4c-42cc-8373-e7690d318104", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15575', 0, 65, '09-mitre-attack', 'retrieved', '9168A432944EF004800047D7A799327009579CA115D50AD49BCA37E224DE31BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
