VALUES ('doc-09-mitre-attack-p0-15576', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agent.btz](https://attack.mitre.org/software/S0092) drops itself onto removable media devices and creates an autorun.inf file with an instruction to run that file. When the device is inserted into another system, it opens autorun.inf and loads the malware.(Citation: ThreatExpert Agent.btz)", "external_references": [{"description": "Shevchenko, S.. (2008, November 30). Agent.btz - A Threat That Hit Pentagon. Retrieved April 8, 2016.", "source_name": "ThreatExpert Agent.btz", "url": "http://blog.threatexpert.com/2008/11/agentbtz-threat-that-hit-pentagon.html"}], "id": "relationship--7f3c015e-d95d-4d35-a583-236134464554", "modified": "2026-04-29T14:23:06.099Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--40d3e230-ed32-469f-ba89-be70cc08ab39", "spec_version": "2.1", "target_ref": "attack-pattern--3b744087-9945-4a6f-91e8-9dbceda417a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15576', 0, 88, '09-mitre-attack', 'retrieved', '2A9C15D7940077672BD317E5F7C505CBD614F2FD257E51208C5B622114C76B7C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
