VALUES ('doc-09-mitre-attack-p0-15577', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agent.btz](https://attack.mitre.org/software/S0092) creates a file named thumb.dd on all USB flash drives connected to the victim. This file contains information about the infected system and activity logs.(Citation: Securelist Agent.btz)", "external_references": [{"description": "Gostev, A.. (2014, March 12). Agent.btz: a Source of Inspiration?. Retrieved April 8, 2016.", "source_name": "Securelist Agent.btz", "url": "https://securelist.com/agent-btz-a-source-of-inspiration/58551/"}], "id": "relationship--8b96fb11-8b54-4bed-9e6c-cd93b29c5c20", "modified": "2026-04-29T14:23:06.116Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--40d3e230-ed32-469f-ba89-be70cc08ab39", "spec_version": "2.1", "target_ref": "attack-pattern--a3e1e6c5-9c74-4fc0-a16c-a9d228c17829", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15577', 0, 78, '09-mitre-attack', 'retrieved', '0B743ED5A1B933686CEEBC152D9B6D98B0228DBD5A30A7FD5300D096A79DE930', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
