VALUES ('doc-09-mitre-attack-p0-15633', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FLASHFLOOD](https://attack.mitre.org/software/S0036) achieves persistence by making an entry in the Registry''s Run key.(Citation: FireEye APT30)", "external_references": [{"description": "FireEye Labs. (2015, April). APT30 AND THE MECHANICS OF A LONG-RUNNING CYBER ESPIONAGE OPERATION. Retrieved November 17, 2024.", "source_name": "FireEye APT30", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2015/05/20081935/rpt-apt30.pdf"}], "id": "relationship--3ebad12d-fd33-4289-93dc-1f5af5e90b66", "modified": "2026-04-29T14:23:06.010Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--43213480-78f7-4fb3-976f-d48f5f6a4c2a", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15633', 0, 68, '09-mitre-attack', 'retrieved', 'EA9D322D384B2ECF3B59A0A92B5DDCD65C844628C8EBC4B1D2D2D86B61DF0E1C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
