INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-15635', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FLASHFLOOD](https://attack.mitre.org/software/S0036) searches for interesting files (either a default or customized set of file extensions) on removable media and copies them to a staging area. The default file types copied would include data copied to the drive by [SPACESHIP](https://attack.mitre.org/software/S0035).(Citation: FireEye APT30)", "external_references": [{"description": "FireEye Labs. (2015, April). APT30 AND THE MECHANICS OF A LONG-RUNNING CYBER ESPIONAGE OPERATION. Retrieved November 17, 2024.", "source_name": "FireEye APT30", "url": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/43/2015/05/20081935/rpt-apt30.pdf"}], "id": "relationship--e30a790b-8f09-4bdc-8116-275d00880333", "modified": "2026-04-29T14:23:06.234Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--43213480-78f7-4fb3-976f-d48f5f6a4c2a", "spec_version": "2.1", "target_ref": "attack-pattern--1b7ba276-eedc-4951-a762-0ceea2c030ec", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15635', 0, 94, '09-mitre-attack', 'retrieved', 'D15668CE234742F636E4EF8F14ED25D17084440D1845068EF1751E2FF7713D22', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
