VALUES ('doc-09-mitre-attack-p0-15702', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-01-22T18:54:06.133Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoFiSe](https://attack.mitre.org/software/S1101) can save files to be evaluated for further exfiltration in the `C:\\Programdata\\Microsoft\\` and \t`C:\\windows\\temp\\` folders.\n (Citation: Kaspersky ToddyCat Check Logs October 2023)", "external_references": [{"description": "Dedola, G. et al. (2023, October 12). ToddyCat: Keep calm and check logs. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat Check Logs October 2023", "url": "https://securelist.com/toddycat-keep-calm-and-check-logs/110696/"}], "id": "relationship--959bda8e-6c64-4048-9c34-f8ccd64066e8", "modified": "2026-04-29T14:23:06.129Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--452da2d9-706c-4185-ad6f-f5edaf4b9f48", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15702', 0, 80, '09-mitre-attack', 'retrieved', 'E2A9DD70DAEE95302CD4F71256A17506C83CE5102C735127DC924FA6F43E071F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
