VALUES ('doc-09-mitre-attack-p0-15703', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-01-22T18:19:33.731Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoFiSe](https://attack.mitre.org/software/S1101) can collect files of interest from targeted systems.(Citation: Kaspersky ToddyCat Check Logs October 2023)", "external_references": [{"description": "Dedola, G. et al. (2023, October 12). ToddyCat: Keep calm and check logs. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat Check Logs October 2023", "url": "https://securelist.com/toddycat-keep-calm-and-check-logs/110696/"}], "id": "relationship--aa0819dc-ed46-4908-af81-cdcd5c4d1845", "modified": "2026-04-29T14:23:06.156Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--452da2d9-706c-4185-ad6f-f5edaf4b9f48", "spec_version": "2.1", "target_ref": "attack-pattern--3c4a2599-71ee-4405-ba1e-0e28414b4bc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15703', 0, 72, '09-mitre-attack', 'retrieved', '8EAE5D001FBCDC520DF9FB5DBEAC17A975D3DCDB1AA866501E8F919EA213A97C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
