VALUES ('doc-09-mitre-attack-p0-15704', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-01-22T18:42:31.586Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoFiSe](https://attack.mitre.org/software/S1101) can collect all the files from the working directory every three hours and place them into a password-protected archive for further exfiltration.(Citation: Kaspersky ToddyCat Check Logs October 2023)", "external_references": [{"description": "Dedola, G. et al. (2023, October 12). ToddyCat: Keep calm and check logs. Retrieved January 3, 2024.", "source_name": "Kaspersky ToddyCat Check Logs October 2023", "url": "https://securelist.com/toddycat-keep-calm-and-check-logs/110696/"}], "id": "relationship--f3182645-cd5b-43af-b1ec-c1fb9e15f2af", "modified": "2026-04-29T14:23:06.255Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--452da2d9-706c-4185-ad6f-f5edaf4b9f48", "spec_version": "2.1", "target_ref": "attack-pattern--30208d3e-0d6b-43c8-883e-44462a514619", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15704', 0, 86, '09-mitre-attack', 'retrieved', 'B5B1144644F02863A6DDD3C5DEB4FAF83C91C8BFCF9B3E9F8D804061638AC434', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
