VALUES ('doc-09-mitre-attack-p0-15705', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-28T20:27:00.832Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HOPLIGHT](https://attack.mitre.org/software/S0376) can enumerate device drivers located in the registry at `HKLM\\Software\\WBEM\\WDM`.(Citation: US-CERT HOPLIGHT Apr 2019)", "external_references": [{"description": "US-CERT. (2019, April 10). MAR-10135536-8 – North Korean Trojan: HOPLIGHT. Retrieved April 19, 2019.", "source_name": "US-CERT HOPLIGHT Apr 2019", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR19-100A"}], "id": "relationship--04a39f08-17e1-46e8-aba0-db4ef1318ba1", "modified": "2026-04-29T14:23:05.909Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--454fe82d-6fd2-4ac6-91ab-28a33fe01369", "spec_version": "2.1", "target_ref": "attack-pattern--215d9700-5881-48b8-8265-6449dbb7195d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15705', 0, 67, '09-mitre-attack', 'retrieved', '535504506D08E03E836FB4505308761BDF0DED9186D17170B0C0B642D5DA2D49', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
