VALUES ('doc-09-mitre-attack-p0-15707', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-19T16:27:45.836Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HOPLIGHT](https://attack.mitre.org/software/S0376) has multiple C2 channels in place in case one fails.(Citation: US-CERT HOPLIGHT Apr 2019)\t", "external_references": [{"description": "US-CERT. (2019, April 10). MAR-10135536-8 – North Korean Trojan: HOPLIGHT. Retrieved April 19, 2019.", "source_name": "US-CERT HOPLIGHT Apr 2019", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR19-100A"}], "id": "relationship--1708aa35-a362-429f-be06-82dc106dfeb4", "modified": "2026-04-29T14:23:05.936Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--454fe82d-6fd2-4ac6-91ab-28a33fe01369", "spec_version": "2.1", "target_ref": "attack-pattern--f24faf46-3b26-4dbb-98f2-63460498e433", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15707', 0, 67, '09-mitre-attack', 'retrieved', '933218DD17F5E1F8CCE7F8CCEF0B4C76C9EBD17FA975EB3738F2553F9AACC6E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
