VALUES ('doc-09-mitre-attack-p0-15708', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-22T19:39:48.825Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A variant of [HOPLIGHT](https://attack.mitre.org/software/S0376) hooks lsass.exe, and lsass.exe then checks the Registry for the data value ''rdpproto'' under the key SYSTEM\\CurrentControlSet\\Control\\Lsa Name .(Citation: US-CERT HOPLIGHT Apr 2019)", "external_references": [{"description": "US-CERT. (2019, April 10). MAR-10135536-8 – North Korean Trojan: HOPLIGHT. Retrieved April 19, 2019.", "source_name": "US-CERT HOPLIGHT Apr 2019", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR19-100A"}], "id": "relationship--1c548d89-557e-4c48-9b71-8a761d94e77b", "modified": "2026-04-29T14:23:05.943Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--454fe82d-6fd2-4ac6-91ab-28a33fe01369", "spec_version": "2.1", "target_ref": "attack-pattern--c32f7008-9fea-41f7-8366-5eb9b74bd896", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15708', 0, 79, '09-mitre-attack', 'retrieved', 'FFD71FD37768E3F457D1956896ACDDE14982C87316497EEA479A1098BB28C711', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
