VALUES ('doc-09-mitre-attack-p0-15709', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-19T16:27:45.818Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HOPLIGHT](https://attack.mitre.org/software/S0376) has multiple proxy options that mask traffic between the malware and the remote operators.(Citation: US-CERT HOPLIGHT Apr 2019)\t\n", "external_references": [{"description": "US-CERT. (2019, April 10). MAR-10135536-8 – North Korean Trojan: HOPLIGHT. Retrieved April 19, 2019.", "source_name": "US-CERT HOPLIGHT Apr 2019", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR19-100A"}], "id": "relationship--321703ba-7871-46c0-837e-6a2e1dc5aba9", "modified": "2026-04-29T14:23:05.983Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--454fe82d-6fd2-4ac6-91ab-28a33fe01369", "spec_version": "2.1", "target_ref": "attack-pattern--731f4f55-b6d0-41d1-a7a9-072a66389aea", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15709', 0, 71, '09-mitre-attack', 'retrieved', '651B2BFB8A6C8D0D35E01CBC76351459D5DF7E483D234C24E36D4BD1D1872FDC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
