VALUES ('doc-09-mitre-attack-p0-15710', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-30T19:47:22.076Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HOPLIGHT](https://attack.mitre.org/software/S0376) has connected outbound over TCP port 443 with a FakeTLS method.(Citation: US-CERT HOPLIGHT Apr 2019)", "external_references": [{"description": "US-CERT. (2019, April 10). MAR-10135536-8 – North Korean Trojan: HOPLIGHT. Retrieved April 19, 2019.", "source_name": "US-CERT HOPLIGHT Apr 2019", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR19-100A"}], "id": "relationship--36983a10-4fdb-4bfc-83a0-78f4d11e83df", "modified": "2026-04-29T14:23:05.994Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--454fe82d-6fd2-4ac6-91ab-28a33fe01369", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15710', 0, 68, '09-mitre-attack', 'retrieved', 'EBA24558C0A0E28F9376FFA1CD85D2201E247EDBFCEE5111368610514BABAA1C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
