VALUES ('doc-09-mitre-attack-p0-15727', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-20T19:57:31.679Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cuckoo Stealer](https://attack.mitre.org/software/S1153) has copied its binary and the victim''s scraped password into a hidden folder in the `/Users` directory.(Citation: Kandji Cuckoo April 2024)(Citation: SentinelOne Cuckoo Stealer May 2024)", "external_references": [{"description": "Kohler, A. and Lopez, C. (2024, April 30). Malware: Cuckoo Behaves Like Cross Between Infostealer and Spyware. Retrieved August 20, 2024.", "source_name": "Kandji Cuckoo April 2024", "url": "https://www.kandji.io/blog/malware-cuckoo-infostealer-spyware"}, {"description": "Stokes, P. (2024, May 9). macOS Cuckoo Stealer | Ensuring Detection and Defense as New Samples Rapidly Emerge. Retrieved August 20, 2024.", "source_name": "SentinelOne Cuckoo Stealer May 2024", "url": "https://www.sentinelone.com/blog/macos-cuckoo-stealer-ensuring-detection-and-defense-as-new-samples-rapidly-emerge/"}], "id": "relationship--0f54df67-bfb2-40d1-a427-50558f1b1171", "modified": "2026-04-29T14:23:05.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--457a5e8d-d964-4130-bde3-c07bb41a093e", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15727', 0, 118, '09-mitre-attack', 'retrieved', 'AE62B4A95E5E1A93F7D4A985F06F27D486B7D48A2B793827DB6FC8C392C9DED6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
