VALUES ('doc-09-mitre-attack-p0-15753', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-16T15:39:37.921Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GuLoader](https://attack.mitre.org/software/S0561) has the ability to inject shellcode into a donor processes that is started in a suspended state. [GuLoader](https://attack.mitre.org/software/S0561) has previously used RegAsm as a donor process.(Citation: Medium Eli Salem GuLoader April 2021)", "external_references": [{"description": "Salem, E. (2021, April 19). Dancing With Shellcodes: Cracking the latest version of Guloader. Retrieved July 7, 2021.", "source_name": "Medium Eli Salem GuLoader April 2021", "url": "https://elis531989.medium.com/dancing-with-shellcodes-cracking-the-latest-version-of-guloader-75083fb15cb4"}], "id": "relationship--30df477a-f775-4349-ba03-07a3f4293db4", "modified": "2026-04-29T14:23:05.979Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--45c759ac-b490-48bb-80d4-c8eee3431027", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15753', 0, 91, '09-mitre-attack', 'retrieved', 'AF66081C386FB748C0EBB833C771D515CE746C5E4F4A5674735E74E7F37CFF54', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
