VALUES ('doc-09-mitre-attack-p0-15847', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-16T15:07:27.123Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[InvisiMole](https://attack.mitre.org/software/S0260) has used a custom implementation of DNS tunneling to embed C2 communications in DNS requests and replies.(Citation: ESET InvisiMole June 2020)", "external_references": [{"description": "Hromcova, Z. and Cherpanov, A. (2020, June). INVISIMOLE: THE HIDDEN PART OF THE STORY. Retrieved July 16, 2020.", "source_name": "ESET InvisiMole June 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/06/ESET_InvisiMole.pdf"}], "id": "relationship--9c6804dc-e1d5-43f5-97ee-7d827c9d308d", "modified": "2026-04-29T14:23:06.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--47afe41c-4c08-485e-b062-c3bd209a1cce", "spec_version": "2.1", "target_ref": "attack-pattern--1996eef1-ced3-4d7f-bf94-33298cabbf72", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15847', 0, 78, '09-mitre-attack', 'retrieved', '41C96F924CACA91D9422033BB5D0193A4E10E9F5EE0005475BB47E3F773725DC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
