VALUES ('doc-09-mitre-attack-p0-15881', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-16T15:51:25.742Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[InvisiMole](https://attack.mitre.org/software/S0260) can spread within a network via the BlueKeep (CVE-2019-0708) and EternalBlue (CVE-2017-0144) vulnerabilities in RDP and SMB respectively.(Citation: ESET InvisiMole June 2020)", "external_references": [{"description": "Hromcova, Z. and Cherpanov, A. (2020, June). INVISIMOLE: THE HIDDEN PART OF THE STORY. Retrieved July 16, 2020.", "source_name": "ESET InvisiMole June 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/06/ESET_InvisiMole.pdf"}], "id": "relationship--a14c0cae-f7da-42d6-ab3c-f11746233e06", "modified": "2026-08-04T20:30:56.050Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--47afe41c-4c08-485e-b062-c3bd209a1cce", "spec_version": "2.1", "target_ref": "attack-pattern--9db0cf3a-a3c9-4012-8268-123b9db6fd82", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15881', 0, 79, '09-mitre-attack', 'retrieved', 'AE31934C63394DA01936377409C737FB21EAC4B5F0F2B9204418D84D74C65FA7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
