VALUES ('doc-09-mitre-attack-p0-15917', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T20:27:15.180Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Apostle](https://attack.mitre.org/software/S1133) will attempt to delete all event logs on a victim machine following file wipe activity.(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--035ad845-9a13-41bb-b7c1-1bd47d787605", "modified": "2026-04-29T14:23:05.907Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--48d96fa0-d027-45aa-a8c3-5d09f65d596d", "spec_version": "2.1", "target_ref": "attack-pattern--75b9a4d2-d4e2-4ca1-9aab-1badd9e05fd0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15917', 0, 75, '09-mitre-attack', 'retrieved', '2B56246705E647F4A367E3C11ACFBEAF6CBCC85A8A446FF6D724FCCA9677F415', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
