VALUES ('doc-09-mitre-attack-p0-15922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T20:25:54.484Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Apostle](https://attack.mitre.org/software/S1133) searches for files on available drives based on a list of extensions hard-coded into the sample for follow-on wipe activity.(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--cef64d3f-3747-4811-8104-09f63a24b32b", "modified": "2026-04-29T14:23:06.208Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--48d96fa0-d027-45aa-a8c3-5d09f65d596d", "spec_version": "2.1", "target_ref": "attack-pattern--fb640c43-aa6b-431e-a961-a279010424ac", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15922', 0, 80, '09-mitre-attack', 'retrieved', '3E8E77F65998D2BB3C8D76CB7A273F4E1A3E16D9D824B2B55C6C18AF1FCC43A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
