VALUES ('doc-09-mitre-attack-p0-15928', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-25T13:57:35.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Volgmer](https://attack.mitre.org/software/S0180) installs a copy of itself in a randomly selected service, then overwrites the ServiceDLL entry in the service''s Registry entry. Some [Volgmer](https://attack.mitre.org/software/S0180) variants also install .dll files as services with names generated by a list of hard-coded strings.(Citation: US-CERT Volgmer Nov 2017)(Citation: US-CERT Volgmer 2 Nov 2017)(Citation: Symantec Volgmer Aug 2014)", "external_references": [{"description": "US-CERT. (2017, November 01). Malware Analysis Report (MAR) - 10135536-D. Retrieved July 16, 2018.", "source_name": "US-CERT Volgmer 2 Nov 2017", "url": "https://www.us-cert.gov/sites/default/files/publications/MAR-10135536-D_WHITE_S508C.PDF"}, {"description": "US-CERT. (2017, November 22). Alert (TA17-318B): HIDDEN COBRA – North Korean Trojan: Volgmer. Retrieved December 7, 2017.", "source_name": "US-CERT Volgmer Nov 2017", "url": "https://www.us-cert.gov/ncas/alerts/TA17-318B"}, {"description": "Yagi, J. (2014, August 24). Trojan.Volgmer. Retrieved July 16, 2018.", "source_name": "Symantec Volgmer Aug 2014", "url": "https://web.archive.org/web/20181126143456/https://www.symantec.com/security-center/writeup/2014-081811-3237-99?tabid=2"}], "id": "relationship--1436e328-e692-4dbc-adfd-cf1024a98b2e", "modified": "2026-04-29T14:23:05.931Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--495b6cdb-7b5a-4fbc-8d33-e7ef68806d08", "spec_version": "2.1", "target_ref": "attack-pattern--2959d63f-73fd-46a1-abd2-109d7dcede32", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15928', 0, 148, '09-mitre-attack', 'retrieved', 'DA60E7433699B45632F81D5DA32E2EC477A6D4461C521BA8F3FCE45025187C95', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
