VALUES ('doc-09-mitre-attack-p0-15953', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-13T15:08:07.977Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WhisperGate](https://attack.mitre.org/software/S0689) overwrites the MBR with a bootloader component that performs destructive wiping operations on hard drives and displays a fake ransom note when the host boots.(Citation: Crowdstrike WhisperGate January 2022)(Citation: Cybereason WhisperGate February 2022)(Citation: Microsoft WhisperGate January 2022)(Citation: Cisco Ukraine Wipers January 2022)(Citation: Medium S2W WhisperGate January 2022)", "external_references": [{"description": "Biasini, N. et al.. (2022, January 21). Ukraine Campaign Delivers Defacement and Wipers, in Continued Escalation. Retrieved March 14, 2022.", "source_name": "Cisco Ukraine Wipers January 2022", "url": "https://blog.talosintelligence.com/2022/01/ukraine-campaign-delivers-defacement.html"}, {"description": "Crowdstrike. (2022, January 19). Technical Analysis of the WhisperGate Malicious Bootloader. Retrieved March 10, 2022.", "source_name": "Crowdstrike WhisperGate January 2022", "url": "https://www.crowdstrike.com/blog/technical-analysis-of-whispergate-malware"}, {"description": "Cybereason Nocturnus. (2022, February 15). Cybereason vs. WhisperGate and HermeticWiper. Retrieved March 10, 2022.", "source_name": "Cybereason WhisperGate February 2022", "url": "https://www.cybereason.com/blog/cybereason-vs.-whispergate-wiper"}, {"description": "MSTIC. (2022, January 15). Destructive malware targeting Ukrainian organizations. Retrieved March 10, 2022.", "source_name": "Microsoft WhisperGate January 2022", "url": "https://www.microsoft.com/security/blog/2022/01/15/destructive-malware-targeting-ukrainian-organizations/"}, {"description": "S2W. (2022, January 18). Analysis of Destructive Malware (WhisperGate) targeting Ukraine. Retrieved March 14, 2022.", "source_name": "Medium S2W WhisperGate January 2022", "url": "https://medium.com/s2wblog/analysis-of-destructive-malware-whispergate-targeting-ukraine-9d5d158f19f3"}], "id": "relationship--03ecffe3-d09c-40f5-bbc8-ffa4acc4bdb4", "modified": "2026-04-29T14:23:05.908Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--49fee0b0-390e-4bde-97f8-97ed46bd19b7", "spec_version": "2.1", "target_ref": "attack-pattern--1b7b1806-7746-41a1-a35d-e48dae25ddba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15953', 0, 197, '09-mitre-attack', 'retrieved', '922B8AD999724600AEF6AC5EB546B003A894D4BF3B9C9597A1EC0F73496ED50F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
