VALUES ('doc-09-mitre-attack-p0-15955', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-10T18:52:38.096Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WhisperGate](https://attack.mitre.org/software/S0689) can corrupt files by overwriting the first 1 MB with `0xcc` and appending random extensions.(Citation: Microsoft WhisperGate January 2022)(Citation: Crowdstrike WhisperGate January 2022)(Citation: Cybereason WhisperGate February 2022)(Citation: Unit 42 WhisperGate January 2022)(Citation: Cisco Ukraine Wipers January 2022)(Citation: Medium S2W WhisperGate January 2022)", "external_references": [{"description": "Biasini, N. et al.. (2022, January 21). Ukraine Campaign Delivers Defacement and Wipers, in Continued Escalation. Retrieved March 14, 2022.", "source_name": "Cisco Ukraine Wipers January 2022", "url": "https://blog.talosintelligence.com/2022/01/ukraine-campaign-delivers-defacement.html"}, {"description": "Crowdstrike. (2022, January 19). Technical Analysis of the WhisperGate Malicious Bootloader. Retrieved March 10, 2022.", "source_name": "Crowdstrike WhisperGate January 2022", "url": "https://www.crowdstrike.com/blog/technical-analysis-of-whispergate-malware"}, {"description": "Cybereason Nocturnus. (2022, February 15). Cybereason vs. WhisperGate and HermeticWiper. Retrieved March 10, 2022.", "source_name": "Cybereason WhisperGate February 2022", "url": "https://www.cybereason.com/blog/cybereason-vs.-whispergate-wiper"}, {"description": "Falcone, R. et al.. (2022, January 20). Threat Brief: Ongoing Russia and Ukraine Cyber Conflict. Retrieved March 10, 2022.", "source_name": "Unit 42 WhisperGate January 2022", "url": "https://unit42.paloaltonetworks.com/ukraine-cyber-conflict-cve-2021-32648-whispergate/#whispergate-malware-family"}, {"description": "MSTIC. (2022, January 15). Destructive malware targeting Ukrainian organizations. Retrieved March 10, 2022.", "source_name": "Microsoft WhisperGate January 2022", "url": "https://www.microsoft.com/security/blog/2022/01/15/destructive-malware-targeting-ukrainian-organizations/"}, {"description": "S2W. (2022, January 18). Analysis of Destructive Malware (WhisperGate) targeting Ukraine. Retrieved March 14, 2022.", "source_name": "Medium S2W WhisperGate January 2022", "url": "https://medium.com/s2wblog/analysis-of-destructive-malware-whispergate-targeting-ukraine-9d5d158f19f3"}], "id": "relationship--13576b41-ec77-418c-b581-d3fa461df941", "modified": "2026-04-29T14:23:05.930Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--49fee0b0-390e-4bde-97f8-97ed46bd19b7", "spec_version": "2.1", "target_ref": "attack-pattern--d45a3d09-b3cf-48f4-9f0f-f521ee5cb05c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15955', 0, 220, '09-mitre-attack', 'retrieved', '342DCA7B07FB612F65C68828AC671BA2E37D0AFA5C9895A41A7FD4A00D65FAE6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
