VALUES ('doc-09-mitre-attack-p0-15960', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-14T14:16:33.288Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WhisperGate](https://attack.mitre.org/software/S0689) can Base64 encode strings, store downloaded files in reverse byte order, and use the Eazfuscator tool to obfuscate its third stage.(Citation: Cisco Ukraine Wipers January 2022)(Citation: Medium S2W WhisperGate January 2022)(Citation: RecordedFuture WhisperGate Jan 2022)", "external_references": [{"description": "Biasini, N. et al.. (2022, January 21). Ukraine Campaign Delivers Defacement and Wipers, in Continued Escalation. Retrieved March 14, 2022.", "source_name": "Cisco Ukraine Wipers January 2022", "url": "https://blog.talosintelligence.com/2022/01/ukraine-campaign-delivers-defacement.html"}, {"description": "Insikt Group. (2020, January 28). WhisperGate Malware Corrupts Computers in Ukraine. Retrieved September 16, 2024.", "source_name": "RecordedFuture WhisperGate Jan 2022", "url": "https://www.recordedfuture.com/research/whispergate-malware-corrupts-computers-ukraine"}, {"description": "S2W. (2022, January 18). Analysis of Destructive Malware (WhisperGate) targeting Ukraine. Retrieved March 14, 2022.", "source_name": "Medium S2W WhisperGate January 2022", "url": "https://medium.com/s2wblog/analysis-of-destructive-malware-whispergate-targeting-ukraine-9d5d158f19f3"}], "id": "relationship--4d10ce98-d1c1-4e26-84c3-a309e7c30313", "modified": "2026-04-29T14:23:06.030Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--49fee0b0-390e-4bde-97f8-97ed46bd19b7", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-