VALUES ('doc-09-mitre-attack-p0-15973', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-10T21:03:13.269Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WhisperGate](https://attack.mitre.org/software/S0689) can use a Visual Basic script to exclude the `C:\\` drive from Windows Defender.(Citation: Unit 42 WhisperGate January 2022)(Citation: Cisco Ukraine Wipers January 2022)", "external_references": [{"description": "Biasini, N. et al.. (2022, January 21). Ukraine Campaign Delivers Defacement and Wipers, in Continued Escalation. Retrieved March 14, 2022.", "source_name": "Cisco Ukraine Wipers January 2022", "url": "https://blog.talosintelligence.com/2022/01/ukraine-campaign-delivers-defacement.html"}, {"description": "Falcone, R. et al.. (2022, January 20). Threat Brief: Ongoing Russia and Ukraine Cyber Conflict. Retrieved March 10, 2022.", "source_name": "Unit 42 WhisperGate January 2022", "url": "https://unit42.paloaltonetworks.com/ukraine-cyber-conflict-cve-2021-32648-whispergate/#whispergate-malware-family"}], "id": "relationship--af939bf8-559a-494c-ad06-fb3a8b3e0e18", "modified": "2026-04-29T14:23:06.164Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--49fee0b0-390e-4bde-97f8-97ed46bd19b7", "spec_version": "2.1", "target_ref": "attack-pattern--dfd7cc1d-e1d8-4394-a198-97c4cab8aa67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15973', 0, 112, '09-mitre-attack', 'retrieved', 'D6F3989C5071B0D901B32E73E38D1B8A456FD99B5E2D2B3F594A92B1C31BE8D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
