VALUES ('doc-09-mitre-attack-p0-15974', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-14T14:26:05.428Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [WhisperGate](https://attack.mitre.org/software/S0689) third stage can use the AdvancedRun.exe tool to execute commands in the context of the Windows TrustedInstaller group via `%TEMP%\\AdvancedRun.exe\" /EXEFilename \"C:\\Windows\\System32\\sc.exe\" /WindowState 0 /CommandLine \"stop WinDefend\" /StartDirectory \"\" /RunAs 8 /Run`.(Citation: Cisco Ukraine Wipers January 2022)", "external_references": [{"description": "Biasini, N. et al.. (2022, January 21). Ukraine Campaign Delivers Defacement and Wipers, in Continued Escalation. Retrieved March 14, 2022.", "source_name": "Cisco Ukraine Wipers January 2022", "url": "https://blog.talosintelligence.com/2022/01/ukraine-campaign-delivers-defacement.html"}], "id": "relationship--b0ecee81-0bbe-4ab9-9618-b245656aabc4", "modified": "2026-04-29T14:23:06.167Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--49fee0b0-390e-4bde-97f8-97ed46bd19b7", "spec_version": "2.1", "target_ref": "attack-pattern--677569f9-a8b0-459e-ab24-7f18091fa7bf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-15974', 0, 98, '09-mitre-attack', 'retrieved', '0A1B2C8B96000903AFDD8ABEFBBAE10FD537B0ECA5AD59241FE5920E7120B1F8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
