VALUES ('doc-09-mitre-attack-p0-16013', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-25T15:19:24.665Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AcidPour](https://attack.mitre.org/software/S1167) includes a self-delete function where the malware deletes itself from disk after execution and program load into memory.(Citation: SentinelOne AcidPour 2024)", "external_references": [{"description": "Juan Andrés Guerrero-Saade & Tom Hegel. (2024, March 21). AcidPour | New Embedded Wiper Variant of AcidRain Appears in Ukraine. Retrieved November 25, 2024.", "source_name": "SentinelOne AcidPour 2024", "url": "https://www.sentinelone.com/labs/acidpour-new-embedded-wiper-variant-of-acidrain-appears-in-ukraine/"}], "id": "relationship--e833d684-ee9f-43f7-977b-3d2939951c12", "modified": "2026-04-29T14:23:06.241Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4b1b3a36-bbd6-462c-9c03-7fd4fb5e0dfa", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16013', 0, 83, '09-mitre-attack', 'retrieved', 'FE65173B846896F4098D3291486755D0ECE21473A2D39BEA67E002E078FDDE11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
