VALUES ('doc-09-mitre-attack-p0-16043', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-22T14:58:06.557Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Skidmap](https://attack.mitre.org/software/S0468) has checked for the existence of specific files including /usr/sbin/setenforce and /etc/selinux/config . It also has the ability to monitor the cryptocurrency miner file and process. (Citation: Trend Micro Skidmap) ", "external_references": [{"description": "Remillano, A., Urbanec, J. (2019, September 19). Skidmap Linux Malware Uses Rootkit Capabilities to Hide Cryptocurrency-Mining Payload. Retrieved June 4, 2020.", "source_name": "Trend Micro Skidmap", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/skidmap-linux-malware-uses-rootkit-capabilities-to-hide-cryptocurrency-mining-payload/"}], "id": "relationship--472c61e4-e839-4766-b1ce-d9095203e538", "modified": "2026-04-29T14:23:06.022Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4b68b5ea-2e1b-4225-845b-8632f702b9a0", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16043', 0, 90, '09-mitre-attack', 'retrieved', 'DC36239EB71057287EE03EAC3EFC69878337EA61B80E4AD75F3B2DD005B990E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
