VALUES ('doc-09-mitre-attack-p0-16044', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-22T14:58:06.560Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Skidmap](https://attack.mitre.org/software/S0468) has the ability to check if /usr/sbin/setenforce exists. This file controls what mode SELinux is in.(Citation: Trend Micro Skidmap) ", "external_references": [{"description": "Remillano, A., Urbanec, J. (2019, September 19). Skidmap Linux Malware Uses Rootkit Capabilities to Hide Cryptocurrency-Mining Payload. Retrieved June 4, 2020.", "source_name": "Trend Micro Skidmap", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/skidmap-linux-malware-uses-rootkit-capabilities-to-hide-cryptocurrency-mining-payload/"}], "id": "relationship--49f761f9-89d2-4e6f-a0c6-fc5e32cca471", "modified": "2026-04-29T14:23:06.026Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4b68b5ea-2e1b-4225-845b-8632f702b9a0", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16044', 0, 79, '09-mitre-attack', 'retrieved', '8F6387F5CCC84C3133AF391C0F5CC592C80FA84C5A7458EE7206C72E119571BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
