VALUES ('doc-09-mitre-attack-p0-16055', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T21:31:07.631Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Okrum](https://attack.mitre.org/software/S0439)''s loader can check the amount of physical memory and terminates itself if the host has less than 1.5 Gigabytes of physical memory in total.(Citation: ESET Okrum July 2019)", "external_references": [{"description": "Hromcova, Z. (2019, July). OKRUM AND KETRICAN: AN OVERVIEW OF RECENT KE3CHANG GROUP ACTIVITY. Retrieved May 6, 2020.", "source_name": "ESET Okrum July 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/07/ESET_Okrum_and_Ketrican.pdf"}], "id": "relationship--108e61c1-83fc-4ebf-aa5c-4ff19ccbe7cf", "modified": "2026-04-29T14:23:05.926Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4b6ec280-7bbb-48ff-ae59-b189520ebe83", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16055', 0, 85, '09-mitre-attack', 'retrieved', '590A753D32521DD54D448461BCC37BAD1EDC5B0DC916B24C862A4970BDA01923', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
