VALUES ('doc-09-mitre-attack-p0-16089', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T21:27:01.884Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TRANSLATEXT](https://attack.mitre.org/software/S1201) has exfiltrated collected credentials to the C2 server.(Citation: Zscaler Kimsuky TRANSLATEXT) ", "external_references": [{"description": "Park, S. (2024, June 27). Kimsuky deploys TRANSLATEXT to target South Korean academia. Retrieved October 14, 2024.", "source_name": "Zscaler Kimsuky TRANSLATEXT", "url": "https://www.zscaler.com/blogs/security-research/kimsuky-deploys-translatext-target-south-korean-academia#technical-analysis"}], "id": "relationship--3cc0db99-8172-41e5-b386-3488bfb41f43", "modified": "2026-04-29T14:23:06.007Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4b72b6a7-72be-45d9-af02-fdcf0fc6d358", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16089', 0, 67, '09-mitre-attack', 'retrieved', '1A28B5C53F1B4C38A6B23230F350AAEF48E9F54CF24B31139BEF9B7842393059', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
