VALUES ('doc-09-mitre-attack-p0-16090', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T21:28:23.577Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TRANSLATEXT](https://attack.mitre.org/software/S1201) has modified the following registry key to install itself as the value, granting permission to install specified extensions: ` HKCU\\Software\\Policies\\Google\\Chrome\\ExtensionInstallForcelist`.(Citation: Zscaler Kimsuky TRANSLATEXT) ", "external_references": [{"description": "Park, S. (2024, June 27). Kimsuky deploys TRANSLATEXT to target South Korean academia. Retrieved October 14, 2024.", "source_name": "Zscaler Kimsuky TRANSLATEXT", "url": "https://www.zscaler.com/blogs/security-research/kimsuky-deploys-translatext-target-south-korean-academia#technical-analysis"}], "id": "relationship--4a2d2699-a2c0-40e4-8e8d-3450155b9923", "modified": "2026-04-29T14:23:06.026Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4b72b6a7-72be-45d9-af02-fdcf0fc6d358", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16090', 0, 79, '09-mitre-attack', 'retrieved', '9316125A1D90D4AFB225EADE2EDF954DEFC79EE883A52C1981191BC5C581DD56', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
