VALUES ('doc-09-mitre-attack-p0-16125', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T17:57:46.663Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Line Dancer](https://attack.mitre.org/software/S1186) can hook both the crash dump process and the Autehntication, Authorization, and Accounting (AAA) functions on compromised machines to evade forensic analysis and authentication mechanisms.(Citation: Cisco ArcaneDoor 2024)", "external_references": [{"description": "Cisco Talos. (2024, April 24). ArcaneDoor - New espionage-focused campaign found targeting perimeter network devices. Retrieved January 6, 2025.", "source_name": "Cisco ArcaneDoor 2024", "url": "https://blog.talosintelligence.com/arcanedoor-new-espionage-focused-campaign-found-targeting-perimeter-network-devices/"}], "id": "relationship--95283b95-4474-47ac-9e77-a1f4da968f9f", "modified": "2026-04-29T14:23:06.128Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4c8ad4ed-3bbb-4088-bf14-f4caf2bf62a0", "spec_version": "2.1", "target_ref": "attack-pattern--0f20e3cb-245b-4a61-8a91-2d93f7cb0e9b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16125', 0, 86, '09-mitre-attack', 'retrieved', '656A98060BFA1C845CD71FE51E5EB9A87FB11A198F238C8378DD8C90DA6A0D48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
