VALUES ('doc-09-mitre-attack-p0-16149', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-18T18:57:50.045Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Conti](https://attack.mitre.org/software/S0575) can stop up to 146 Windows services related to security, backup, database, and email solutions through the use of net stop .(Citation: CarbonBlack Conti July 2020)", "external_references": [{"description": "Baskin, B. (2020, July 8). TAU Threat Discovery: Conti Ransomware. Retrieved February 17, 2021.", "source_name": "CarbonBlack Conti July 2020", "url": "https://www.carbonblack.com/blog/tau-threat-discovery-conti-ransomware/"}], "id": "relationship--59cb7691-e0a0-4e34-94ae-63d3e22f21c1", "modified": "2026-04-29T14:23:06.047Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4dea7d8e-af94-4bfb-afe4-7ff54f59308b", "spec_version": "2.1", "target_ref": "attack-pattern--20fb2507-d71c-455d-9b6d-6104461cf26b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16149', 0, 79, '09-mitre-attack', 'retrieved', '60D009AF1D08F3454D8A90FC815C8E14BAF107C192FED2B9806B65BA4AC8417A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
