VALUES ('doc-09-mitre-attack-p0-16173', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T14:02:35.774Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) performs several system checks as part of anti-analysis mechanisms, including querying the operating system build number, processor vendor and type, video controller, and CPU temperature.(Citation: HP RaspberryRobin 2024)", "external_references": [{"description": "Patrick Schläpfer . (2024, April 10). Raspberry Robin Now Spreading Through Windows Script Files. Retrieved May 17, 2024.", "source_name": "HP RaspberryRobin 2024", "url": "https://threatresearch.ext.hp.com/raspberry-robin-now-spreading-through-windows-script-files/"}], "id": "relationship--11764f59-a7b9-4dff-8e37-471d739f5343", "modified": "2026-04-29T14:23:05.928Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16173', 0, 85, '09-mitre-attack', 'retrieved', 'F33BE215F9FFB21EF0721CD661F2573A9F91FEB1BBE922BD6A83F45F1CAF0F1B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
