INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-16176', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:48:17.405Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) will check for the presence of several security products on victim machines and will avoid UAC bypass mechanisms if they are identified.(Citation: TrendMicro RaspberryRobin 2022) [Raspberry Robin](https://attack.mitre.org/software/S1130) can use specific cookie values in HTTP requests to command and control infrastructure to validate that requests for second stage payloads originate from the initial downloader script.(Citation: HP RaspberryRobin 2024)", "external_references": [{"description": "Christopher So. (2022, December 20). Raspberry Robin Malware Targets Telecom, Governments. Retrieved May 17, 2024.", "source_name": "TrendMicro RaspberryRobin 2022", "url": "https://www.trendmicro.com/en_us/research/22/l/raspberry-robin-malware-targets-telecom-governments.html"}, {"description": "Patrick Schläpfer . (2024, April 10). Raspberry Robin Now Spreading Through Windows Script Files. Retrieved May 17, 2024.", "source_name": "HP RaspberryRobin 2024", "url": "https://threatresearch.ext.hp.com/raspberry-robin-now-spreading-through-windows-script-files/"}], "id": "relationship--23b1bbb5-ab75-42f7-8bc9-d1c918f6817d", "modified": "2026-04-29T14:23:05.954Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16176', 0, 136, '09-mitre-attack', 'retrieved', '25D563186351C90E0DCBE8F37808020DEB5DA6F9372A75729E0CB86488AF03E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
