VALUES ('doc-09-mitre-attack-p0-16184', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T14:07:04.972Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) retrieves its second stage payload in a variety of ways such as through msiexec.exe abuse, or running the curl command to download the payload to the victim''s %AppData% folder.(Citation: HP RaspberryRobin 2024)(Citation: RedCanary RaspberryRobin 2022)", "external_references": [{"description": "Lauren Podber and Stef Rand. (2022, May 5). Raspberry Robin gets the worm early. Retrieved May 17, 2024.", "source_name": "RedCanary RaspberryRobin 2022", "url": "https://redcanary.com/blog/threat-intelligence/raspberry-robin/"}, {"description": "Patrick Schläpfer . (2024, April 10). Raspberry Robin Now Spreading Through Windows Script Files. Retrieved May 17, 2024.", "source_name": "HP RaspberryRobin 2024", "url": "https://threatresearch.ext.hp.com/raspberry-robin-now-spreading-through-windows-script-files/"}], "id": "relationship--538697e9-2dda-43cb-ba43-208402f62f9d", "modified": "2026-04-29T14:23:06.039Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16184', 0, 117, '09-mitre-attack', 'retrieved', '9C2E66DCC13753C91AC8136112AA2A45D18B083586F096977A2C73ED48593A93', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
