VALUES ('doc-09-mitre-attack-p0-16187', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:34:51.988Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) has historically used infected USB media to spread to new victims.(Citation: TrendMicro RaspberryRobin 2022)(Citation: RedCanary RaspberryRobin 2022)", "external_references": [{"description": "Christopher So. (2022, December 20). Raspberry Robin Malware Targets Telecom, Governments. Retrieved May 17, 2024.", "source_name": "TrendMicro RaspberryRobin 2022", "url": "https://www.trendmicro.com/en_us/research/22/l/raspberry-robin-malware-targets-telecom-governments.html"}, {"description": "Lauren Podber and Stef Rand. (2022, May 5). Raspberry Robin gets the worm early. Retrieved May 17, 2024.", "source_name": "RedCanary RaspberryRobin 2022", "url": "https://redcanary.com/blog/threat-intelligence/raspberry-robin/"}], "id": "relationship--66810009-f426-4cee-8514-21d00753ae7a", "modified": "2026-04-29T14:23:06.064Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--3b744087-9945-4a6f-91e8-9dbceda417a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16187', 0, 96, '09-mitre-attack', 'retrieved', '9B8E9728977C115306FB90BF01746212D4654EB5311DB151982DCFDE5C27F692', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
