INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-16188', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:16:36.511Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) uses outbound HTTP requests containing victim information for retrieving second stage payloads.(Citation: RedCanary RaspberryRobin 2022) Variants of [Raspberry Robin](https://attack.mitre.org/software/S1130) can download archive files (such as 7-Zip files) via the victim web browser for second stage execution.(Citation: HP RaspberryRobin 2024)", "external_references": [{"description": "Lauren Podber and Stef Rand. (2022, May 5). Raspberry Robin gets the worm early. Retrieved May 17, 2024.", "source_name": "RedCanary RaspberryRobin 2022", "url": "https://redcanary.com/blog/threat-intelligence/raspberry-robin/"}, {"description": "Patrick Schläpfer . (2024, April 10). Raspberry Robin Now Spreading Through Windows Script Files. Retrieved May 17, 2024.", "source_name": "HP RaspberryRobin 2024", "url": "https://threatresearch.ext.hp.com/raspberry-robin-now-spreading-through-windows-script-files/"}], "id": "relationship--6731a2dc-622a-4547-9b43-3eba8443dd49", "modified": "2026-04-29T14:23:06.065Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16188', 0, 121, '09-mitre-attack', 'retrieved', '6E732918AFFA9576288E782F53D685D35AFB1FF460B030A5B2766F91315F0020', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
