VALUES ('doc-09-mitre-attack-p0-16189', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-23T18:22:28.494Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) will execute a legitimate process, then suspend it to inject code for a [Tor](https://attack.mitre.org/software/S0183) client into the process, followed by resumption of the process to enable [Tor](https://attack.mitre.org/software/S0183) client execution.(Citation: TrendMicro RaspberryRobin 2022)", "external_references": [{"description": "Christopher So. (2022, December 20). Raspberry Robin Malware Targets Telecom, Governments. Retrieved May 17, 2024.", "source_name": "TrendMicro RaspberryRobin 2022", "url": "https://www.trendmicro.com/en_us/research/22/l/raspberry-robin-malware-targets-telecom-governments.html"}], "id": "relationship--71db7381-ad59-4eb0-80b4-505c38eea9d2", "modified": "2026-04-29T14:23:06.081Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--b200542e-e877-4395-875b-cf1a44537ca4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16189', 0, 86, '09-mitre-attack', 'retrieved', '49796B3F980C58F69A7AAA7834A6F81B4ED4E8799D97593D7B8F2F03CD59EAD0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
