VALUES ('doc-09-mitre-attack-p0-16190', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:23:14.079Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) uses newly-registered domains containing only a few characters for command and controll purposes, such as \" v0[.]cx \".(Citation: RedCanary RaspberryRobin 2022)", "external_references": [{"description": "Lauren Podber and Stef Rand. (2022, May 5). Raspberry Robin gets the worm early. Retrieved May 17, 2024.", "source_name": "RedCanary RaspberryRobin 2022", "url": "https://redcanary.com/blog/threat-intelligence/raspberry-robin/"}], "id": "relationship--72ebbe49-a354-4894-bfa2-06016f3d1ae6", "modified": "2026-04-29T14:23:06.082Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--40f5caa0-4cb7-4117-89fc-d421bb493df3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16190', 0, 78, '09-mitre-attack', 'retrieved', '129AC6791A4E1EC2F8AFE89BE80461D2461B8DFC3DF01B81109E94BE048F558F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
