VALUES ('doc-09-mitre-attack-p0-16194', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:50:50.280Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) creates an elevated COM object for CMLuaUtil and uses this to set a registry value that points to the malicious LNK file during execution.(Citation: TrendMicro RaspberryRobin 2022)", "external_references": [{"description": "Christopher So. (2022, December 20). Raspberry Robin Malware Targets Telecom, Governments. Retrieved May 17, 2024.", "source_name": "TrendMicro RaspberryRobin 2022", "url": "https://www.trendmicro.com/en_us/research/22/l/raspberry-robin-malware-targets-telecom-governments.html"}], "id": "relationship--9180d2f8-0bfe-40f3-a92b-36de31df76b4", "modified": "2026-04-29T14:23:06.123Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--2f6b4ed7-fef1-44ba-bcb8-1b4beb610b64", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16194', 0, 81, '09-mitre-attack', 'retrieved', '81DD4BE5585CBC56E93A57F8065D0CD0ED838A4A2F9E59D4C298F1C278B8735C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
