VALUES ('doc-09-mitre-attack-p0-16196', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:20:42.880Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) uses cmd.exe to read and execute a file stored on an infected USB device as part of initial installation.(Citation: RedCanary RaspberryRobin 2022)", "external_references": [{"description": "Lauren Podber and Stef Rand. (2022, May 5). Raspberry Robin gets the worm early. Retrieved May 17, 2024.", "source_name": "RedCanary RaspberryRobin 2022", "url": "https://redcanary.com/blog/threat-intelligence/raspberry-robin/"}], "id": "relationship--91f0a77b-0c70-425e-afe0-af5f8296c434", "modified": "2026-04-29T14:23:06.124Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16196', 0, 79, '09-mitre-attack', 'retrieved', 'DB240BFA64847E86C8B124A793F4FAFC820CC64B5E20240AE15CFD7E7331466C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
