VALUES ('doc-09-mitre-attack-p0-16197', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:27:35.271Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) uses the Windows utility odbcconf.exe to execute malicious commands, using the regsvr flag to execute DLLs and bypass application control mechanisms that are not monitoring for odbcconf.exe abuse.(Citation: RedCanary RaspberryRobin 2022)", "external_references": [{"description": "Lauren Podber and Stef Rand. (2022, May 5). Raspberry Robin gets the worm early. Retrieved May 17, 2024.", "source_name": "RedCanary RaspberryRobin 2022", "url": "https://redcanary.com/blog/threat-intelligence/raspberry-robin/"}], "id": "relationship--9648bb23-1d68-4d76-bc42-e371889e4acf", "modified": "2026-04-29T14:23:06.130Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--6e3bd510-6b33-41a4-af80-2d80f3ee0071", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16197', 0, 88, '09-mitre-attack', 'retrieved', 'F1850BAA5949D0E2C00555AF803A12A4DE5F75EF6675734141200906B0DD9977', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
