VALUES ('doc-09-mitre-attack-p0-16200', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T15:45:25.666Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) execution can rely on users directly interacting with malicious LNK files.(Citation: Microsoft RaspberryRobin 2022)", "external_references": [{"description": "Microsoft Threat Intelligence. (2022, October 27). Raspberry Robin worm part of larger ecosystem facilitating pre-ransomware activity. Retrieved May 17, 2024.", "source_name": "Microsoft RaspberryRobin 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/10/27/raspberry-robin-worm-part-of-larger-ecosystem-facilitating-pre-ransomware-activity/"}], "id": "relationship--a6a6e8e2-c9c2-40b9-b410-ea84b2c43caf", "modified": "2026-04-29T14:23:06.152Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--8c32eb4d-805f-4fc5-bf60-c4d476c131b5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16200', 0, 73, '09-mitre-attack', 'retrieved', '4CD6B4AF6BD0DD24CC93D33565AFDE0CE7BF6E289B886C8C36A67CECE90B8177', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
