VALUES ('doc-09-mitre-attack-p0-16203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T14:04:36.061Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) can delete its initial delivery script from disk during execution.(Citation: HP RaspberryRobin 2024)", "external_references": [{"description": "Patrick Schläpfer . (2024, April 10). Raspberry Robin Now Spreading Through Windows Script Files. Retrieved May 17, 2024.", "source_name": "HP RaspberryRobin 2024", "url": "https://threatresearch.ext.hp.com/raspberry-robin-now-spreading-through-windows-script-files/"}], "id": "relationship--c5d32f1b-d4c1-4811-9793-ee55e663a2d6", "modified": "2026-04-29T14:23:06.196Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16203', 0, 70, '09-mitre-attack', 'retrieved', 'F19349DFA108AEE4E068D778BE7E6C58B332BC03F41C396F524DDE68CBA16435', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
