VALUES ('doc-09-mitre-attack-p0-16204', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T13:37:26.796Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) contains several layers of obfuscation to hide malicious code from detection and analysis.(Citation: TrendMicro RaspberryRobin 2022)", "external_references": [{"description": "Christopher So. (2022, December 20). Raspberry Robin Malware Targets Telecom, Governments. Retrieved May 17, 2024.", "source_name": "TrendMicro RaspberryRobin 2022", "url": "https://www.trendmicro.com/en_us/research/22/l/raspberry-robin-malware-targets-telecom-governments.html"}], "id": "relationship--c9a2ee9a-4787-47c0-9cdc-f52735f066ad", "modified": "2026-04-29T14:23:06.201Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16204', 0, 70, '09-mitre-attack', 'retrieved', '289D6F396F2EA1DC1753C70BBD94657D20F2342BA9B7E3624D838CEEB900F2ED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
