VALUES ('doc-09-mitre-attack-p0-16206', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-17T15:46:57.518Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Raspberry Robin](https://attack.mitre.org/software/S1130) uses a RunOnce Registry key for persistence, where the key is removed after its use on reboot then re-added by the malware after it resumes execution.(Citation: Microsoft RaspberryRobin 2022)", "external_references": [{"description": "Microsoft Threat Intelligence. (2022, October 27). Raspberry Robin worm part of larger ecosystem facilitating pre-ransomware activity. Retrieved May 17, 2024.", "source_name": "Microsoft RaspberryRobin 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/10/27/raspberry-robin-worm-part-of-larger-ecosystem-facilitating-pre-ransomware-activity/"}], "id": "relationship--d788ad3e-64e3-41ac-9075-2732d95afb57", "modified": "2026-04-29T14:23:06.220Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e385fa6-ebe0-43fc-9ccf-5b51b5dc4d79", "spec_version": "2.1", "target_ref": "attack-pattern--d2c4e5ea-dbdf-4113-805a-b1e2a337fb33", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16206', 0, 88, '09-mitre-attack', 'retrieved', 'FC6311EC85BF71AC3DA0F48EC53B3807E990B687E32B288A397C2E1481C1A682', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
