VALUES ('doc-09-mitre-attack-p0-16221', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-15T20:20:36.538Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mispadu](https://attack.mitre.org/software/S1122) has relied on users to execute malicious files in order to gain execution on victim machines.(Citation: ESET Security Mispadu Facebook Ads 2019)(Citation: Metabase Q Mispadu Trojan 2023)(Citation: SCILabs Malteiro 2021)", "external_references": [{"description": "ESET Security. (2019, November 19). Mispadu: Advertisement for a discounted Unhappy Meal. Retrieved March 13, 2024.", "source_name": "ESET Security Mispadu Facebook Ads 2019", "url": "https://www.welivesecurity.com/2019/11/19/mispadu-advertisement-discounted-unhappy-meal/"}, {"description": "Garcia, F., Regalado, D. (2023, March 7). Inside Mispadu massive infection campaign in LATAM. Retrieved March 15, 2024.", "source_name": "Metabase Q Mispadu Trojan 2023", "url": "https://www.metabaseq.com/mispadu-banking-trojan/"}, {"description": "SCILabs. (2021, December 23). Cyber Threat Profile Malteiro. Retrieved March 13, 2024.", "source_name": "SCILabs Malteiro 2021", "url": "https://blog.scilabs.mx/en/cyber-threat-profile-malteiro/"}], "id": "relationship--4f5d4ab0-6514-4a99-a5b9-456c903e4717", "modified": "2026-04-29T14:23:06.033Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e6464d2-69df-4e56-8d4c-1973f84d7b80", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16221', 0, 133, '09-mitre-attack', 'retrieved', '3F4EAA29ACA4553250CD4450B8A05589ED847FD6F5D6520D1EFFE923DFCB849C', 'v1', '{"source_id": "09-mitre-at