VALUES ('doc-09-mitre-attack-p0-16224', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-15T20:37:09.882Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mispadu](https://attack.mitre.org/software/S1122) can log keystrokes on the victim''s machine.(Citation: ESET Security Mispadu Facebook Ads 2019)(Citation: Metabase Q Mispadu Trojan 2023)(Citation: SCILabs URSA/Mispadu Evolution 2023)", "external_references": [{"description": "ESET Security. (2019, November 19). Mispadu: Advertisement for a discounted Unhappy Meal. Retrieved March 13, 2024.", "source_name": "ESET Security Mispadu Facebook Ads 2019", "url": "https://www.welivesecurity.com/2019/11/19/mispadu-advertisement-discounted-unhappy-meal/"}, {"description": "Garcia, F., Regalado, D. (2023, March 7). Inside Mispadu massive infection campaign in LATAM. Retrieved March 15, 2024.", "source_name": "Metabase Q Mispadu Trojan 2023", "url": "https://www.metabaseq.com/mispadu-banking-trojan/"}, {"description": "SCILabs. (2023, May 23). Evolution of banking trojan URSA/Mispadu. Retrieved March 13, 2024.", "source_name": "SCILabs URSA/Mispadu Evolution 2023", "url": "https://blog.scilabs.mx/en/evolution-of-banking-trojan-ursa-mispadu/"}], "id": "relationship--668b180d-a227-4585-98ee-55dddd6eea92", "modified": "2026-04-29T14:23:06.064Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e6464d2-69df-4e56-8d4c-1973f84d7b80", "spec_version": "2.1", "target_ref": "attack-pattern--09a60ea3-a8d1-4ae5-976e-5783248b72a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16224', 0, 127, '09-mitre-attack', 'retrieved', 'C3D08FA24B92D3DC59B2CD5A884A890CFB212B771662BC0E39585A617F51A192', 'v1', '{"source_id": "09-mitre-attack