VALUES ('doc-09-mitre-attack-p0-16225', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-13T21:43:56.980Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mispadu](https://attack.mitre.org/software/S1122) creates a link in the startup folder for persistence.(Citation: ESET Security Mispadu Facebook Ads 2019) [Mispadu](https://attack.mitre.org/software/S1122) adds persistence via the registry key `HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run`.(Citation: Metabase Q Mispadu Trojan 2023)", "external_references": [{"description": "ESET Security. (2019, November 19). Mispadu: Advertisement for a discounted Unhappy Meal. Retrieved March 13, 2024.", "source_name": "ESET Security Mispadu Facebook Ads 2019", "url": "https://www.welivesecurity.com/2019/11/19/mispadu-advertisement-discounted-unhappy-meal/"}, {"description": "Garcia, F., Regalado, D. (2023, March 7). Inside Mispadu massive infection campaign in LATAM. Retrieved March 15, 2024.", "source_name": "Metabase Q Mispadu Trojan 2023", "url": "https://www.metabaseq.com/mispadu-banking-trojan/"}], "id": "relationship--6c9c0332-bdd8-4692-af01-cc7ebc486a41", "modified": "2026-04-29T14:23:06.073Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e6464d2-69df-4e56-8d4c-1973f84d7b80", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16225', 0, 112, '09-mitre-attack', 'retrieved', '349A1943BF865ADD8D13CFA3B618F8B1CB6FBC90815706C4B764D1291EDA94FB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
