VALUES ('doc-09-mitre-attack-p0-16226', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-15T18:04:26.232Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mispadu](https://attack.mitre.org/software/S1122) uses a custom algorithm to obfuscate its internal strings and uses hardcoded keys.(Citation: ESET Security Mispadu Facebook Ads 2019)\n\n[Mispadu](https://attack.mitre.org/software/S1122) also uses encoded configuration files and has encoded payloads using Base64.(Citation: ESET Security Mispadu Facebook Ads 2019)(Citation: SCILabs Malteiro 2021)(Citation: SCILabs Malteiro Threat Overlap 2023)", "external_references": [{"description": "ESET Security. (2019, November 19). Mispadu: Advertisement for a discounted Unhappy Meal. Retrieved March 13, 2024.", "source_name": "ESET Security Mispadu Facebook Ads 2019", "url": "https://www.welivesecurity.com/2019/11/19/mispadu-advertisement-discounted-unhappy-meal/"}, {"description": "SCILabs. (2021, December 23). Cyber Threat Profile Malteiro. Retrieved March 13, 2024.", "source_name": "SCILabs Malteiro 2021", "url": "https://blog.scilabs.mx/en/cyber-threat-profile-malteiro/"}, {"description": "SCILabs. (2023, October 8). URSA/Mispadu: Overlap analysis with other threats. Retrieved March 13, 2024.", "source_name": "SCILabs Malteiro Threat Overlap 2023", "url": "https://blog.scilabs.mx/en/ursa-mispadu-overlap-analysis-with-other-threats/"}], "id": "relationship--6fbd8e04-ce24-4969-9f3e-2df874eceb04", "modified": "2026-04-29T14:23:06.078Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e6464d2-69df-4e56-8d4c-1973f84d7b80", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-829