VALUES ('doc-09-mitre-attack-p0-16229', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-29T14:04:56.834Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mispadu](https://attack.mitre.org/software/S1122) can monitor browser activity for online banking actions and display full-screen overlay images to block user access to the intended site or present additional data fields.(Citation: Segurança Informática URSA Sophisticated Loader 2020)(Citation: SCILabs Malteiro 2021)", "external_references": [{"description": "Pedro Tavares (Segurança Informática). (2020, September 15). Threat analysis: The emergent URSA trojan impacts many countries using a sophisticated loader. Retrieved March 13, 2024.", "source_name": "Segurança Informática URSA Sophisticated Loader 2020", "url": "https://seguranca-informatica.pt/threat-analysis-the-emergent-ursa-trojan-impacts-many-countries-using-a-sophisticated-loader/"}, {"description": "SCILabs. (2021, December 23). Cyber Threat Profile Malteiro. Retrieved March 13, 2024.", "source_name": "SCILabs Malteiro 2021", "url": "https://blog.scilabs.mx/en/cyber-threat-profile-malteiro/"}], "id": "relationship--aa6411df-8f39-4368-9b35-45cc2a7394d8", "modified": "2026-04-29T14:23:06.157Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e6464d2-69df-4e56-8d4c-1973f84d7b80", "spec_version": "2.1", "target_ref": "attack-pattern--a2029942-0a85-4947-b23c-ca434698171d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16229', 0, 119, '09-mitre-attack', 'retrieved', '5F46AA81055B86EA2AEA313C1C1DEACAE92E640150C5ABCAA210B9AB22D330A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "ST