VALUES ('doc-09-mitre-attack-p0-16231', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-15T20:25:19.551Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mispadu](https://attack.mitre.org/software/S1122) can run checks to verify if it is running within a virtualized environments including Hyper-V, VirtualBox or VMWare and will terminate execution if the computer name is “JOHN-PC.”(Citation: ESET Security Mispadu Facebook Ads 2019)(Citation: SCILabs Malteiro 2021)", "external_references": [{"description": "ESET Security. (2019, November 19). Mispadu: Advertisement for a discounted Unhappy Meal. Retrieved March 13, 2024.", "source_name": "ESET Security Mispadu Facebook Ads 2019", "url": "https://www.welivesecurity.com/2019/11/19/mispadu-advertisement-discounted-unhappy-meal/"}, {"description": "SCILabs. (2021, December 23). Cyber Threat Profile Malteiro. Retrieved March 13, 2024.", "source_name": "SCILabs Malteiro 2021", "url": "https://blog.scilabs.mx/en/cyber-threat-profile-malteiro/"}], "id": "relationship--b53c54de-bbd9-4862-92e1-86b60091cb15", "modified": "2026-04-29T14:23:06.173Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4e6464d2-69df-4e56-8d4c-1973f84d7b80", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16231', 0, 113, '09-mitre-attack', 'retrieved', 'D227026584157B0F8B6EE1A654E4B1A5CE6D3EBEE31C39E636AFFB6E8BDEB151', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
