VALUES ('doc-09-mitre-attack-p0-16266', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-09T19:29:03.455Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [REPTILE](https://attack.mitre.org/software/S1219) launcher can daemonize a process.(Citation: Google Cloud Mandiant UNC3886 2024)", "external_references": [{"description": " Punsaen Boonyakarn, Shawn Chew, Logeswaran Nadarajan, Mathew Potaczek, Jakub Jozwiak, and Alex Marvi. (2024, June 18). Cloaked and Covert: Uncovering UNC3886 Espionage Operations. Retrieved September 24, 2024.", "source_name": "Google Cloud Mandiant UNC3886 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/uncovering-unc3886-espionage-operations"}], "id": "relationship--05237661-caaa-4527-b926-55dc6367383f", "modified": "2026-04-29T14:23:05.910Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4ea492ee-36f8-4017-938f-d01ce951ef94", "spec_version": "2.1", "target_ref": "attack-pattern--573ad264-1371-4ae0-8482-d2673b719dba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16266', 0, 79, '09-mitre-attack', 'retrieved', 'D9F6651F9F2A277C79891E89CD92903FD22BE7935CE6DF9DB26A8D8F7E1163DC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
