VALUES ('doc-09-mitre-attack-p0-16285', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-06T15:53:34.933Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Doki](https://attack.mitre.org/software/S0600)’s container was configured to bind the host root directory.(Citation: Intezer Doki July 20)", "external_references": [{"description": "Fishbein, N., Kajiloti, M.. (2020, July 28). Watch Your Containers: Doki Infecting Docker Servers in the Cloud. Retrieved March 30, 2021.", "source_name": "Intezer Doki July 20", "url": "https://www.intezer.com/blog/cloud-security/watch-your-containers-doki-infecting-docker-servers-in-the-cloud/"}], "id": "relationship--46dd6393-93c7-4e61-8a47-ceecd5b77589", "modified": "2026-04-29T14:23:06.022Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4f1c389e-a80e-4a3e-9b0e-9be8c91df64f", "spec_version": "2.1", "target_ref": "attack-pattern--4a5b7ade-8bb5-4853-84ed-23f262002665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16285', 0, 73, '09-mitre-attack', 'retrieved', 'EE73DEECE0834E20FA8921842166AED4395F8C355C5AD5A0B1C91C08AAD073E4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
