VALUES ('doc-09-mitre-attack-p0-16302', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-18T15:26:55.687Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Siloscape](https://attack.mitre.org/software/S0623) maps the host’s C drive to the container by creating a global symbolic link to the host through the calling of NtSetInformationSymbolicLink .(Citation: Unit 42 Siloscape Jun 2021)", "external_references": [{"description": "Prizmant, D. (2021, June 7). Siloscape: First Known Malware Targeting Windows Containers to Compromise Cloud Environments. Retrieved June 9, 2021.", "source_name": "Unit 42 Siloscape Jun 2021", "url": "https://unit42.paloaltonetworks.com/siloscape/"}], "id": "relationship--6c91f220-34c0-4d9a-8e23-e1a4b29742dc", "modified": "2026-04-29T14:23:06.073Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4fbd565b-bf55-4ac7-80b4-b183a7b64b9c", "spec_version": "2.1", "target_ref": "attack-pattern--4a5b7ade-8bb5-4853-84ed-23f262002665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16302', 0, 88, '09-mitre-attack', 'retrieved', '6A2B362B75EC6C4CEC1D0D877BC32D0567AE1D94D12D50555248352E47F6393A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
