VALUES ('doc-09-mitre-attack-p0-16304', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-18T15:26:55.711Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Siloscape](https://attack.mitre.org/software/S0623) has decrypted the password of the C2 server with a simple byte by byte XOR. [Siloscape](https://attack.mitre.org/software/S0623) also writes both an archive of [Tor](https://attack.mitre.org/software/S0183) and the unzip binary to disk from data embedded within the payload using Visual Studio’s Resource Manager.(Citation: Unit 42 Siloscape Jun 2021)", "external_references": [{"description": "Prizmant, D. (2021, June 7). Siloscape: First Known Malware Targeting Windows Containers to Compromise Cloud Environments. Retrieved June 9, 2021.", "source_name": "Unit 42 Siloscape Jun 2021", "url": "https://unit42.paloaltonetworks.com/siloscape/"}], "id": "relationship--95fc8b91-eda2-49e9-b2fb-b3cdfacc0eaa", "modified": "2026-04-29T14:23:06.129Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4fbd565b-bf55-4ac7-80b4-b183a7b64b9c", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16304', 0, 105, '09-mitre-attack', 'retrieved', '2D4F6E125E2DC93C2533EBAFEC93F0540F43202CFA108387E8BCC17E5596E5BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
