VALUES ('doc-09-mitre-attack-p0-16305', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-18T15:26:55.655Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Siloscape](https://attack.mitre.org/software/S0623) can run cmd through an IRC channel.(Citation: Unit 42 Siloscape Jun 2021)", "external_references": [{"description": "Prizmant, D. (2021, June 7). Siloscape: First Known Malware Targeting Windows Containers to Compromise Cloud Environments. Retrieved June 9, 2021.", "source_name": "Unit 42 Siloscape Jun 2021", "url": "https://unit42.paloaltonetworks.com/siloscape/"}], "id": "relationship--9a88636a-3ac1-4068-91df-82c51fa97086", "modified": "2026-04-29T14:23:06.136Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--4fbd565b-bf55-4ac7-80b4-b183a7b64b9c", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16305', 0, 72, '09-mitre-attack', 'retrieved', '4C87105F529684F5164DC9B847AC6AC7A19A50571263A0FD6D146939DF3D0AA4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
