VALUES ('doc-09-mitre-attack-p0-16320', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T17:47:12.590Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RustyWater](https://attack.mitre.org/software/S9037) has used `CreateObject` to instantiate a WScript.Shell Component Object Model (COM) object.(Citation: CloudSEK_RustyWater_Jan2026) Additionally, [RustyWater](https://attack.mitre.org/software/S9037) has used `VirtualAllocEx` and `WriteProcessMemory` to inject shellcode into explorer.exe.(Citation: CloudSEK_RustyWater_Jan2026) ", "external_references": [{"description": "Awasthi, P. (2026, January 8). Reborn in Rust: Muddy Water Evolves Tooling with RustyWater Implant. Retrieved March 19, 2026.", "source_name": "CloudSEK_RustyWater_Jan2026", "url": "https://www.cloudsek.com/blog/reborn-in-rust-muddywater-evolves-tooling-with-rustywater-implant"}], "id": "relationship--3d32732f-e0ca-4ec7-833a-2eae547c2c44", "modified": "2026-04-29T14:23:06.008Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--50be4e81-db74-41a2-a9aa-423314082bea", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16320', 0, 82, '09-mitre-attack', 'retrieved', '138A81FCA4BF0193D7B95F9709BA116AF1BA1D224155443A388241989606B7A9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
