VALUES ('doc-09-mitre-attack-p0-16321', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T17:55:52.485Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RustyWater](https://attack.mitre.org/software/S9037) has encrypted encoded data with XOR before sending it to the C2 server.(Citation: CloudSEK_RustyWater_Jan2026) ", "external_references": [{"description": "Awasthi, P. (2026, January 8). Reborn in Rust: Muddy Water Evolves Tooling with RustyWater Implant. Retrieved March 19, 2026.", "source_name": "CloudSEK_RustyWater_Jan2026", "url": "https://www.cloudsek.com/blog/reborn-in-rust-muddywater-evolves-tooling-with-rustywater-implant"}], "id": "relationship--4114a4a5-c9e7-4f61-90f3-4a13789a6b37", "modified": "2026-04-29T14:23:06.014Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--50be4e81-db74-41a2-a9aa-423314082bea", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16321', 0, 70, '09-mitre-attack', 'retrieved', 'FBD9F1393A6992B916F412C15909D905E91E32DEDC05C61420296B57412A72C7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
