VALUES ('doc-09-mitre-attack-p0-16322', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T17:56:40.909Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RustyWater](https://attack.mitre.org/software/S9037) has injected its shellcode into explorer.exe by allocating memory via `VirtualAllocEx`, then by writing the payload via `WriteProcessMemory`.(Citation: CloudSEK_RustyWater_Jan2026) ", "external_references": [{"description": "Awasthi, P. (2026, January 8). Reborn in Rust: Muddy Water Evolves Tooling with RustyWater Implant. Retrieved March 19, 2026.", "source_name": "CloudSEK_RustyWater_Jan2026", "url": "https://www.cloudsek.com/blog/reborn-in-rust-muddywater-evolves-tooling-with-rustywater-implant"}], "id": "relationship--5d580ddf-51b4-4849-b54f-a6fed828ba86", "modified": "2026-04-29T14:23:06.053Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--50be4e81-db74-41a2-a9aa-423314082bea", "spec_version": "2.1", "target_ref": "attack-pattern--806a49c4-970d-43f9-9acc-ac0ee11e6662", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16322', 0, 75, '09-mitre-attack', 'retrieved', '1024855FBF7EB019F7D4CFF2719F918405307C7D98276705D2A506891C529698', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
