VALUES ('doc-09-mitre-attack-p0-16325', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T17:49:31.856Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RustyWater](https://attack.mitre.org/software/S9037) has gathered the domain membership of the victim machine’s user.(Citation: CloudSEK_RustyWater_Jan2026) ", "external_references": [{"description": "Awasthi, P. (2026, January 8). Reborn in Rust: Muddy Water Evolves Tooling with RustyWater Implant. Retrieved March 19, 2026.", "source_name": "CloudSEK_RustyWater_Jan2026", "url": "https://www.cloudsek.com/blog/reborn-in-rust-muddywater-evolves-tooling-with-rustywater-implant"}], "id": "relationship--8ac91e9e-447c-4def-9f4a-9c29c355c832", "modified": "2026-04-29T14:23:06.114Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--50be4e81-db74-41a2-a9aa-423314082bea", "spec_version": "2.1", "target_ref": "attack-pattern--21875073-b0ee-49e3-9077-1e2a885359af", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16325', 0, 67, '09-mitre-attack', 'retrieved', 'EE9AE07181D2FF8235F35F99486A2E7E92F396303EB10D6BF919095A2F64BA0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
