VALUES ('doc-09-mitre-attack-p0-16377', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-15T19:18:56.457Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IcedID](https://attack.mitre.org/software/S0483) has been executed through Word and Excel files with malicious embedded macros and through ISO and LNK files that execute the malicious DLL.(Citation: Juniper IcedID June 2020)(Citation: DFIR_Quantum_Ransomware)(Citation: DFIR_Sodinokibi_Ransomware)", "external_references": [{"description": "DFIR. (2021, March 29). Sodinokibi (aka REvil) Ransomware. Retrieved July 22, 2024.", "source_name": "DFIR_Sodinokibi_Ransomware", "url": "https://thedfirreport.com/2021/03/29/sodinokibi-aka-revil-ransomware/"}, {"description": "DFIR. (2022, April 25). Quantum Ransomware. Retrieved July 26, 2024.", "source_name": "DFIR_Quantum_Ransomware", "url": "https://thedfirreport.com/2022/04/25/quantum-ransomware/"}, {"description": "Kimayong, P. (2020, June 18). COVID-19 and FMLA Campaigns used to install new IcedID banking malware. Retrieved July 14, 2020.", "source_name": "Juniper IcedID June 2020", "url": "https://blogs.juniper.net/en-us/threat-research/covid-19-and-fmla-campaigns-used-to-install-new-icedid-banking-malware"}], "id": "relationship--7b078d28-1724-474c-8668-a6d5c28ed72b", "modified": "2026-04-29T14:23:06.094Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5147ef15-1cae-4707-8ea1-bee8d98b7f1d", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16377', 0, 120, '09-mitre-attack', 'retrieved', 'F883FB78BCAEC5C7D54C7082919D1A15C9D9998048E2740E40231948B6EC30DB', 'v1', '{"source_