VALUES ('doc-09-mitre-attack-p0-16378', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-05T22:23:09.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IcedID](https://attack.mitre.org/software/S0483) can identify AV products on an infected host using the following command:\n` WMIC.exe WMIC /Node:localhost /Namespace:\\\\root\\SecurityCenter2 Path AntiVirusProduct Get * /Format:List`.(Citation: DFIR_Sodinokibi_Ransomware)(Citation: DFIR_Quantum_Ransomware)", "external_references": [{"description": "DFIR. (2021, March 29). Sodinokibi (aka REvil) Ransomware. Retrieved July 22, 2024.", "source_name": "DFIR_Sodinokibi_Ransomware", "url": "https://thedfirreport.com/2021/03/29/sodinokibi-aka-revil-ransomware/"}, {"description": "DFIR. (2022, April 25). Quantum Ransomware. Retrieved July 26, 2024.", "source_name": "DFIR_Quantum_Ransomware", "url": "https://thedfirreport.com/2022/04/25/quantum-ransomware/"}], "id": "relationship--7f81539c-f287-4f8f-be26-11443d2e19d3", "modified": "2026-04-29T14:23:06.100Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5147ef15-1cae-4707-8ea1-bee8d98b7f1d", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16378', 0, 86, '09-mitre-attack', 'retrieved', '3773BFA643F8674530E1099189B2277B845B086946E13E665A8CB5A80DAB44B3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
