VALUES ('doc-09-mitre-attack-p0-16392', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-15T19:02:25.131Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IcedID](https://attack.mitre.org/software/S0483) has used web injection attacks to redirect victims to spoofed sites designed to harvest banking and other credentials. [IcedID](https://attack.mitre.org/software/S0483) can use a self signed TLS certificate in connection with the spoofed site and simultaneously maintains a live connection with the legitimate site to display the correct URL and certificates in the browser.(Citation: IBM IcedID November 2017)(Citation: Juniper IcedID June 2020)", "external_references": [{"description": "Kessem, L., et al. (2017, November 13). New Banking Trojan IcedID Discovered by IBM X-Force Research. Retrieved July 14, 2020.", "source_name": "IBM IcedID November 2017", "url": "https://securityintelligence.com/new-banking-trojan-icedid-discovered-by-ibm-x-force-research/"}, {"description": "Kimayong, P. (2020, June 18). COVID-19 and FMLA Campaigns used to install new IcedID banking malware. Retrieved July 14, 2020.", "source_name": "Juniper IcedID June 2020", "url": "https://blogs.juniper.net/en-us/threat-research/covid-19-and-fmla-campaigns-used-to-install-new-icedid-banking-malware"}], "id": "relationship--c5e3e18d-124e-4ae2-a95c-9db8f6d53000", "modified": "2026-04-29T14:23:06.196Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--5147ef15-1cae-4707-8ea1-bee8d98b7f1d", "spec_version": "2.1", "target_ref": "attack-pattern--544b0346-29ad-41e1-a808-501bb4193f47", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16392', 0, 147, '09-mitre-attack', 'retrieved', 'B8BA321D7705B6560