VALUES ('doc-09-mitre-attack-p0-16422', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-25T22:27:37.813Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Nightdoor](https://attack.mitre.org/software/S1147) can utilize Microsoft OneDrive or Google Drive for command and control purposes.(Citation: ESET EvasivePanda 2024)(Citation: Symantec Daggerfly 2024)", "external_references": [{"description": "Ahn Ho, Facundo Muñoz, & Marc-Etienne M.Léveillé. (2024, March 7). Evasive Panda leverages Monlam Festival to target Tibetans. Retrieved July 25, 2024.", "source_name": "ESET EvasivePanda 2024", "url": "https://www.welivesecurity.com/en/eset-research/evasive-panda-leverages-monlam-festival-target-tibetans/"}, {"description": "Threat Hunter Team. (2024, July 23). Daggerfly: Espionage Group Makes Major Update to Toolset. Retrieved July 25, 2024.", "source_name": "Symantec Daggerfly 2024", "url": "https://symantec-enterprise-blogs.security.com/threat-intelligence/daggerfly-espionage-updated-toolset"}], "id": "relationship--01e1f755-740d-4744-ac81-4f6300b6c857", "modified": "2026-04-29T14:23:05.905Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--51f78dfc-52f9-424e-8753-bb4246188313", "spec_version": "2.1", "target_ref": "attack-pattern--830c9528-df21-472c-8c14-a036bf17d665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-16422', 0, 103, '09-mitre-attack', 'retrieved', 'D27C551CC2620A2EAFB2A285904E92F2B76D5266B2C5435A2B86C508F94B292D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
